mapper.insert:

   SELECT (IFNULL(MAX(SN), 0)+1) sn from PUSH_DEVICE WHERE UUID = #{uuid}

INSERT INTO PUSH_DEVICE (SN, UUID, NTWRK_DEVICE_INFO, OS_VER, DEVICE_NM, USEYN, OS_TYPE, TOKEN_ID)
VALUES (#{sn}, #{uuid}, #{ntwrkDeviceInfo}, #{osVer}, #{deviceNm}, #{useYn}, #{osType}, #{tokenId})

mapper.select:
SELECT SN, UUID, NTWRK_DEVICE_INFO, OS_VER, DEVICE_NM, USEYN, OS_TYPE, TOKEN_ID
FROM PUSH_DEVICE
WHERE USEYN='Y'
	AND UUID = #{uuid}
ORDER BY SN DESC

	LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:

   SELECT (IFNULL(MAX(SN), 0)+1) sn from PUSH_MESSAGE WHERE UUID = #{uuid}

INSERT INTO PUSH_MESSAGE (SN, UUID, MESSAGE, SND_DT, TOKEN_ID)
VALUES (#{sn}, #{uuid}, #{message}, #{sndDt}, #{tokenId})

mapper.select:
SELECT SN, UUID, MESSAGE, SND_DT, TOKEN_ID
FROM PUSH_MESSAGE
	WHERE UUID = #{uuid}
ORDER BY SN DESC

	LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*)
FROM PUSH_MESSAGE
	WHERE UUID = #{uuid}
